// Generated by scaffold-migration-prod — one-time migration baseline.
import 'reflect-metadata';
import { MigrationExecutor } from 'typeorm';
import { AppDataSource as ds } from './data-source';

/**
 * One-time migration BASELINE.
 *
 * Marks every migration currently in the repo as "already applied" WITHOUT
 * executing any of them. Run this exactly ONCE when adopting migrations on a
 * database whose schema was built by the ORM's auto-sync (e.g. production that
 * ran with synchronize on) — it creates the `migrations` bookkeeping table and
 * records all existing migrations, so a later `migration:run` executes only NEW
 * migrations instead of replaying all of history against an already-populated
 * schema (which would fail).
 *
 * Safety:
 *  - Forces synchronize + migrationsRun OFF before connecting. The shared
 *    data-source enables those via env in dev, and initialize() would otherwise
 *    auto-sync / auto-run against a live DB — baseline must only RECORD.
 *  - Only INSERTs bookkeeping rows; never calls any migration up().
 *  - Idempotent: re-running finds nothing pending and is a no-op.
 */
async function main(): Promise<void> {
    ds.setOptions({ synchronize: false, migrationsRun: false });
    await ds.initialize();

    const executor = new MigrationExecutor(ds);
    // Creates the `migrations` table if absent, then returns every migration
    // not yet recorded (all of them, on a freshly-created table).
    const pending = await executor.getPendingMigrations();

    if (pending.length === 0) {
        console.log('[baseline] nothing to do — migrations table is already current.');
        await ds.destroy();
        return;
    }

    const queryRunner = ds.createQueryRunner();
    try {
        for (const migration of pending) {
            await queryRunner.query(
                `INSERT INTO "migrations"("timestamp", "name") VALUES ($1, $2)`,
                [migration.timestamp, migration.name],
            );
            console.log(`[baseline] marked applied: ${migration.name}`);
        }
    } finally {
        await queryRunner.release();
    }

    console.log(
        `[baseline] done — ${pending.length} migrations recorded as applied (none executed).`,
    );
    await ds.destroy();
}

main().catch((err) => {
    console.error('[baseline] failed:', err);
    process.exit(1);
});
